SELECT rno, replyText, replyer, board_bno AS bno, regDate, modDate
FROM reply
WHERE rno = #{rno}

SELECT rno, replyText, replyer, board_bno AS bno, regDate, modDate
FROM reply
WHERE board_bno = #{bno}
ORDER BY rno ASC
LIMIT #{pageRequestDTO.skip}, #{pageRequestDTO.size}

SELECT COUNT(rno) 
FROM reply 
WHERE board_bno = #{bno}
